import sys

def generate_array(N):
    if N == 1:
        return [1]
    elif N == 2:
        return [2, 1]
    else:
        # Start with the smallest possible numbers
        array = []
        current_number = 1
        while len(array) < N:
            if len(array) % 2 == 0:
                array.append(current_number)
            else:
                array.append(current_number + 1)
            current_number += 1
            if current_number > 1000:
